function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=String(text);if(cls)n.className=cls;return n}function clear(n){n.replaceChildren()}function msg(t){$('message').textContent=t;$('message').classList.toggle('hidden',!t)}
function val(v,f='—'){return v===undefined||v===null||v===''?f:String(v)}function sclass(v){v=String(v||'unknown').toLowerCase();if(['pass','passed','accepted','complete','completed','current'].includes(v))return'pass';if(['fail','failed','rejected','error','stale'].includes(v))return'failed';if(['pending','deferred','running','queued'].includes(v))return'pending';return'blocked'}function badge(v){return el('span',val(v,'unknown'),`status ${sclass(v)}`)}
function refId(r){return r&&typeof r==='object'?(r.artifact_id||r.id):r}function link(label,r){const id=refId(r);if(!id)return null;const a=el('a',label);a.href=`/api/artifacts/${encodeURIComponent(id)}/download`;a.download='';return a}
function artifactRef(v){return v&&typeof v==='object'&&typeof v.artifact_id==='string'&&typeof v.sha256==='string'&&Number.isInteger(v.version)}function artifactKey(v){return artifactRef(v)?`${v.artifact_id}:${v.version}:${v.sha256}`:''}function extractHash(v){if(typeof v==='string')return v;if(!v||typeof v!=='object')return displayValue(v);return v.sha256||v.extract_sha256||v.digest||v.hash||displayValue(v)}function currentAssessmentFresh(){return state.assessment?.current_policy===true&&state.assessment?.current_implementation===true}function runtimeCurrentForPolicy(){return state.assessment?.source_runtime_current===true}function requireRuntimeCurrentForPolicy(){if(!runtimeCurrentForPolicy())throw Error('이전 실행 버전의 저장 결과에는 정책 결정이나 계산을 제출할 수 없습니다. 설계 화면에서 현재 코드로 새 설계를 실행하세요.')}function followupPresentation(){const assessmentFollowup=state.assessment?.expert_followup;if(currentAssessmentFresh()&&assessmentFollowup)return{followup:assessmentFollowup,sourceOnly:false};return{followup:state.policy?.followup||null,sourceOnly:true}}function verifiedFollowupSourceSHA(){if(!currentAssessmentFresh())return'';const sha=state.assessment?.expert_followup?.source?.sha256;return typeof sha==='string'&&sha.trim()?sha.trim():''}
function proteinEvidenceCandidates(){const refs=[],seen=new Set;function add(item){const kind=String(item?.registered_type||item?.kind||'').toLowerCase(),ref=item?.ref||item;if(!['protein_h','protein_hydrogen'].includes(kind)||!artifactRef(ref))return;const key=`${ref.artifact_id}:${ref.version}:${ref.sha256}`;if(!seen.has(key)){seen.add(key);refs.push(ref)}}(state.assessment?.registered_evidence||[]).forEach(add);(state.assessment?.evidence_refs||[]).forEach(add);return refs.reverse()}
