async function api(path,opt={},timeout=15000){const c=new AbortController(),timer=setTimeout(()=>c.abort(),timeout);state.controllers.add(c);try{const r=await fetch(path,{...opt,signal:c.signal,credentials:'same-origin'});let b=null;try{b=await r.json()}catch{}if(!r.ok){const d=b?.detail;throw Error(typeof d==='object'?(d.message||d.code):d||`HTTP ${r.status}`)}return b}catch(e){if(e.name==='AbortError')throw Error('요청 시간이 초과되었습니다. 자동 재시도하지 않습니다.');throw e}finally{clearTimeout(timer);state.controllers.delete(c)}}function post(p,b,t){return api(p,{method:'POST',headers:{'Content-Type':'application/json','X-TPD-Local':'1'},body:JSON.stringify(b)},t)}
