function validateProtocolDiagnostic(row,expectedId=null){if(!row||typeof row!=='object'||typeof row.id!=='string'||!/^pdiag-[a-f0-9]{32}$/.test(row.id)||row.job_id!==jobId||(expectedId&&row.id!==expectedId)||!row.source_binding||typeof row.source_binding!=='object'||Array.isArray(row.source_binding)||!row.summary||typeof row.summary!=='object'||Array.isArray(row.summary)||!row.measurement_verification||typeof row.measurement_verification!=='object'||Array.isArray(row.measurement_verification)||row.status!==PROTOCOL_DIAGNOSTIC_STATUS||row.scientific_approved!==false||row.formal_acceptance!==false||row.gates_affected!==false)throw Error('추가 계산의 범위 또는 미검수 상태를 검증하지 못했습니다.');return row}
function protocolJSON(value){const pre=el('pre');if(value===undefined||value===null){pre.textContent='미관측';return pre}try{pre.textContent=JSON.stringify(value,null,2)}catch{pre.textContent='세부 정보를 표시할 수 없습니다.'}return pre}
