async function createProtocolReassessment(){const reasons=protocolReassessmentReasons();if(reasons.length)throw Error(reasons.join(' '));const protocol_ids=[...state.selectedProtocolIds];state.protocolReassessmentBusy=true;renderProtocolDiagnostics();try{const made=await post(`/api/lab/jobs/${encodeURIComponent(jobId)}/scientific-assessments`,{expected_result_sha256:state.job?.result?.files?.json?.sha256||null,protocol_ids},120000);const newId=made?.assessment_id||made?.id;if(!newId)throw Error('서버가 새 평가 ID를 반환하지 않았습니다.');state.selectedAssessmentId=newId;await reloadAssessments(newId);if(state.assessment?.id!==newId)throw Error('생성된 새 평가 revision을 불러오지 못했습니다.');state.selectedProtocolIds.clear();msg('');renderAll()}finally{state.protocolReassessmentBusy=false;renderProtocolDiagnostics()}}
function flatten(v,p='',out=[]){if(v&&typeof v==='object'){Object.entries(v).forEach(([k,x])=>flatten(x,p?`${p}.${k}`:k,out))}else out.push([p,val(v)]);return out}function kv(value){const root=el('div',undefined,'kv');flatten(value).forEach(([k,v])=>{const row=el('div');row.append(el('b',k||'value'),el('span',v));root.append(row)});return root}
function candidateRows(){return state.job?.result?.protac_candidates||[]}function analogRows(){return state.job?.result?.analogs||[]}function expectedMicroReports(){return analogRows().filter(x=>x?.selected===true&&x?.pipeline_status==='qualified'&&typeof x.id==='string'&&x.id)}function numericalMinimum(kind){const root=state.policy?.numerical_criteria;if(!root||typeof root!=='object')return null;const exactNames=new Set(kind==='calibration'?['calibration_seeds_min','calibration_seed_min']:['novel_ternary_repeats_min','ternary_repeats_min','ternary_seeds_min']);let exact=null,fallback=null;function walk(value,path=[]){if(value&&typeof value==='object'){Object.entries(value).forEach(([key,item])=>walk(item,[...path,key]));return}const number=Number(value),key=String(path.at(-1)||'').toLowerCase(),joined=path.join('.').toLowerCase();if(!Number.isInteger(number)||number<1)return;if(exactNames.has(key)&&exact===null)exact=number;const matchesKind=kind==='calibration'?joined.includes('calibration')&&/(seed|repeat)/.test(joined):joined.includes('ternary')&&/(seed|repeat)/.test(joined);if(matchesKind&&/(min|minimum|floor)/.test(joined)&&fallback===null)fallback=number}walk(root);return exact??fallback}function renderSeedPolicyHints(){for(const [kind,id,label] of [['calibration','calibrationSeedHint','Calibration'],['ternary','ternarySeedHint','Novel ternary repeat']]){const node=$(id),minimum=numericalMinimum(kind);if(node)node.textContent=`현재 정책 numerical_criteria의 ${label} 최소 수: ${minimum===null?'unknown':minimum}. 빈 필드는 사전 승인이 아닙니다. placeholder 값은 관찰된 seed를 입력 후보로 제시한 것이며 전문가가 수용한 seed 정책이 아닙니다.`}}function parentRows(){return state.catalog?.reference_parents?.available||[]}function fillSelect(node,rows,idKey,labelKey=idKey){clear(node);const blank=el('option','선택하세요');blank.value='';node.append(blank);rows.forEach(r=>{const o=el('option',val(r[labelKey],r[idKey]));o.value=r[idKey];node.append(o)})}
