function rerunReasons(){const reasons=[],a=state.assessment,p=state.policy,h=state.health,parent=state.job?.result?.parent_scope?.actual_design_parent_id,limits=state.job?.limits;if(!state.session?.actor)reasons.push('검수자 로그인이 필요합니다.');if(h?.read_only)reasons.push('열람 전용 환경입니다.');if(h?.review_only)reasons.push('검토 기록 전용 환경에서는 설계 작업을 시작할 수 없습니다.');if(!a?.id)reasons.push('현재 평가가 없습니다.');if(a&&a.current_policy!==true)reasons.push('현재 정책과 평가 revision이 일치해야 합니다.');if(a&&a.source_inputs_current!==true)reasons.push('설계 source 입력이 최신이 아닙니다.');if(a&&a.source_runtime_current!==true)reasons.push('설계 runtime이 최신이 아닙니다.');if(a&&a.current_implementation!==true)reasons.push('평가 구현이 최신이 아닙니다.');if(Number(p?.revision)<1||!Array.isArray(p?.active_policy_decision_ids)||p.active_policy_decision_ids.length<1)reasons.push('수용되어 활성화된 전문가 정책이 1개 이상 필요합니다.');if(!parent)reasons.push('실제 설계 parent를 확인할 수 없습니다.');if(!limits||![limits.max_calls,limits.max_total_tokens,limits.max_output_tokens,limits.max_elapsed_seconds].every(x=>Number.isFinite(x)&&x>0))reasons.push('Workbench 실행 한도를 확인할 수 없습니다.');if(state.jobs.some(x=>x?.id!==state.job?.id&&['queued','running'].includes(x?.state)))reasons.push('이미 실행 중인 Workbench 작업이 있습니다.');return reasons}
