function addContact(){const r=el('div',undefined,'contact-row'),idLabel=el('label','요구사항 ID'),idInput=el('input');idInput.className='cid';idInput.required=true;idLabel.append(idInput);r.append(idLabel);const kindLabel=el('label','접촉 종류'),kind=el('select');kind.className='ckind';kind.required=true;[['','선택하세요'],['directional_hbond','방향성 수소 결합'],['salt_bridge','염다리'],['aromatic','방향족 상호작용'],['hydrophobic','소수성 접촉'],['proximity','근접 접촉']].forEach(([value,label])=>{const option=el('option',label);option.value=value;kind.append(option)});kindLabel.append(kind);r.append(kindLabel);for(const [n,c,p] of [['Ligand atom maps','clig','쉼표로 구분'],['고급: 실제 protein atom IDs','cprot','A:123:RES:ATOM 형식, 쉼표로 구분']]){const l=el('label',n),i=el('input');i.className=c;i.required=true;i.placeholder=p;l.append(i);r.append(l)}const l=el('label','필수 조건'),i=el('input');i.type='checkbox';i.className='creq';l.append(i);r.append(l);const b=el('button','삭제');b.type='button';b.onclick=()=>r.remove();r.append(b);$('contactRows').append(r)}$('addContact').onclick=addContact;addContact();
