$('microstateForm').onsubmit=async e=>{e.preventDefault();try{requirePopulationWritable();const reportId=$('microReport').value,indexText=$('microIndex').value.trim(),index=Number(indexText),pHText=$('phValue').value.trim(),pH=Number(pHText);if(!reportId||indexText===''||!Number.isInteger(index)||index<0)throw Error('Analog과 0 이상의 state index를 선택하세요.');if(pHText===''||!Number.isFinite(pH)||pH<0||pH>14)throw Error('0부터 14 사이의 유한한 pH를 입력하세요.');state.microChoices[reportId]=index;renderMicroChoices();const expected=expectedMicroReports().map(x=>x.id),missing=expected.filter(id=>!Object.prototype.hasOwnProperty.call(state.microChoices,id));if(missing.length)throw Error(`모든 selected qualified analog의 state를 입력하세요. 누락된 선택: ${missing.join(', ')}`);const sourceKeys=populationSourceMap(),reviewKeys=populationReviewMap(),reports=state.populationRegistry.interaction_reports||[];if(state.populationRows.some(x=>!sourceKeys.has(artifactKey(x.evidence_ref))||!reviewKeys.has(artifactKey(x.review_ref))))throw Error('취소되었거나 현재 목록에 없는 source/review가 포함되어 제출할 수 없습니다.');if(state.populationRows.some(x=>!Number.isInteger(x.state_index)||x.state_index<0||!Number.isFinite(x.pH)||x.pH<0||x.pH>14||x.pH!==pH||state.microChoices[x.analog_id]!==x.state_index))throw Error('Population 행의 pH와 state index는 현재 선택과 정확히 일치해야 합니다.');if(state.populationRows.some(x=>!reports.some(r=>r.analog_id===x.analog_id&&r.report_id===x.report_id&&artifactRef(r.ref))))throw Error('Population 행에는 선택한 analog의 현재 등록 interaction report가 필요합니다.');const choices=Object.fromEntries(expected.map(id=>[id,state.microChoices[id]]));await submit(decision('microstate_decision',{state_choices:choices,pH_conditions:{pH,description:$('phConditions').value.trim()},population_evidence:state.populationRows},'전문가 microstate 조건'))}catch(x){msg(x.message)}};
$('stateSetAnalog').onchange=renderStateSetReview;
$('stateSetReviewForm').onsubmit=async e=>{e.preventDefault();try{if(state.loading)throw Error('현재 assessment 로딩이 끝날 때까지 기다리세요.');if(!state.session?.actor)throw Error('검수자 로그인이 필요합니다.');if(state.health?.read_only)throw Error('열람 전용 환경에서는 저장할 수 없습니다.');if(!state.assessment?.id)throw Error('현재 assessment가 없습니다.');const allowed=['W-c2afc5e73c1a','W-4c0a639c0a41','W-80f8f4a11b5d'],analogId=$('stateSetAnalog').value,poseIndex=Number($('stateSetPose').value);if(!allowed.includes(analogId))throw Error('허용된 analog 3개 중 하나를 선택하세요.');if(!analogRows().some(x=>x?.id===analogId&&x?.selected===true))throw Error('선택한 analog가 현재 작업의 selected analog에 포함되어야 합니다.');if(!Number.isInteger(poseIndex)||poseIndex<0||poseIndex>4)throw Error('Pose index는 0부터 4 사이의 정수여야 합니다.');const observations=$('stateSetObservations').value.trim();if(!observations)throw Error('비교 observations를 입력하세요.');const followupSHA=verifiedFollowupSourceSHA();if(!followupSHA)throw Error('현재 assessment의 검증된 follow-up source SHA-256이 필요합니다.');const resultSHA=state.assessment.source_binding?.result_sha256;if(typeof resultSHA!=='string'||!resultSHA.trim())throw Error('현재 작업 result SHA-256을 확인할 수 없습니다.');const n19=[...document.querySelectorAll('input[name="stateSetN19"]:checked')].map(x=>x.value);if(!n19.includes('neutral')||!n19.includes('protonated'))throw Error('N19 neutral과 protonated 상태를 모두 비교에 포함하세요.');let map5001=null,stateSet=n19.map(n19_state=>({n19:n19_state}));if(analogId==='W-80f8f4a11b5d'){map5001=[...document.querySelectorAll('input[name="stateSetMap5001"]:checked')].map(x=>x.value);if(!map5001.includes('neutral')||!map5001.includes('protonated'))throw Error('W-80f8f4a11b5d에는 map5001 neutral/protonated 조합을 모두 포함하세요.');stateSet=n19.flatMap(n19_state=>map5001.map(map5001_state=>({n19:n19_state,map5001:map5001_state})))}const note={purpose:'diagnostic_state_set_review',job_id:jobId,result_sha256:resultSHA.trim(),followup_source_sha256:followupSHA,assessment_id:state.assessment.id,analog_id:analogId,pose_index:poseIndex,state_set:stateSet,state_population_evidence:$('statePopulationEvidence').value.trim()||null,observations,selected_state:null,approval:false,policy_decision:false,microstate_gate_effect:'none'};state.stateSetStatement=await post('/api/scientific-statements',{text:JSON.stringify(note),locator:'/state-set-review'});renderStateSetReview()}catch(x){msg(x.message)}};
$('geometryTemplateButton').onclick=async()=>{try{$('geometryTemplateButton').disabled=true;$('geometryReviewStatus').textContent='등록된 ternary report preview를 불러오는 중입니다. 자동 재시도하지 않습니다.';await loadGeometryTemplate()}catch(x){msg(x.message);$('geometryReviewStatus').textContent='템플릿을 불러오지 못했습니다. 입력값을 자동 선택하거나 자동 재시도하지 않았습니다.'}finally{renderGeometryReview()}};
$('geometryReviewForm').onsubmit=async e=>{e.preventDefault();try{if(!state.session?.actor)throw Error('검수자 로그인이 필요합니다.');if(state.health?.read_only)throw Error('열람 전용 환경에서는 저장할 수 없습니다.');if(!state.assessment?.id||!currentAssessmentFresh())throw Error('현재 정책 및 구현과 일치하는 assessment가 필요합니다.');requireRuntimeCurrentForPolicy();const reason=$('geometryReviewRationale').value.trim();if(!reason)throw Error('전체 geometry review rationale을 입력하세요.');const branches=validateGeometryBranches(jsonInput('geometryBranches'));await submit(decision('followup_geometry_review',{branches,source_ref:sourceRef()},reason))}catch(x){msg(x.message)}};
