$('ternaryForm').onsubmit=async e=>{e.preventDefault();try{const reason=$('geometryReason').value.trim(),seeds=integerList('ternarySeeds',numericalMinimum('ternary')??1);await submit(decision('ternary_criterion',{chosen_candidates:{CRBN:[$('ternaryCrbn').value],VHL:[$('ternaryVhl').value]},expected_seeds:seeds,geometry:{accepted:true,metric:$('geometryMetric').value.trim(),comparison:$('geometryComparison').value,threshold:Number($('geometryThreshold').value),reference_free:true,rationale:reason,source_ref:sourceRef()}},reason))}catch(x){msg(x.message)}};
$('synthesisForm').onsubmit=async e=>{e.preventDefault();try{const reason=$('synthesisReason').value,chosen=selected('synthesisCandidates'),policies=jsonInput('candidatePolicies'),routes=jsonInput('routeRecords');if(!Array.isArray(policies)||!Array.isArray(routes))throw Error('candidate_policies와 exact_route_records는 JSON 배열이어야 합니다.');if(!chosen.length)throw Error('합성 검토 후보를 선택하세요.');if(routes.some(x=>typeof x?.locator!=='string'||!x.locator.startsWith('/')))throw Error('각 route locator는 source artifact JSON의 /로 시작하는 JSON Pointer여야 합니다.');await submit(decision('synthesis_policy',{chosen_candidate_ids:chosen,candidate_policies:policies,exact_route_records:routes},reason))}catch(x){msg(x.message)}};
$('proteinReviewForm').onsubmit=async e=>{e.preventDefault();try{const evidence=state.proteinEvidence,reason=$('proteinReviewRationale').value.trim(),accepted=$('proteinReviewDisposition').value;if(!evidence||!artifactRef(evidence.ref))throw Error('현재 평가에서 등록된 protein_H 근거를 다시 불러오세요.');if(!reason)throw Error('protein_H 검토 근거를 입력하세요.');if(!['accept','reject'].includes(accepted))throw Error('수용 또는 거절을 선택하세요.');await submit(decision('protein_hydrogen_review',{evidence_ref:evidence.ref,accepted:accepted==='accept',rationale:reason,source_ref:sourceRef()},reason))}catch(x){msg(x.message)}};
