$('rerunButton').onclick=async()=>{try{const reasons=rerunReasons();if(reasons.length)throw Error(reasons.join(' '));const body={result_id:'design:SMARCA2',operation:'design_panel',request_key:crypto.randomUUID(),parameters:{scientific_policy_id:state.assessment.id,parent_id:state.job.result.parent_scope.actual_design_parent_id,exploratory:false,dock:true,use_api:state.health?.llm_enabled===true,panel_size:12}};$('rerunButton').disabled=true;$('rerunButton').textContent='새 설계 작업 등록 중…';const made=await post('/api/lab/jobs',body);if(!made?.job_id)throw Error('서버가 새 작업 ID를 반환하지 않았습니다.');location.assign(`/design?job_id=${encodeURIComponent(made.job_id)}`)}catch(x){msg(x.message);$('rerunButton').textContent='현재 전문가 site 정책으로 설계 다시 실행';renderActions()}};
